def transform(grid):
    h, w = len(grid), len(grid[0])
    # Read the colors of the horizontal bands along the first column
    # containing repeated non-background divider markers.
    rows = [r for r in range(h) if len(set(grid[r])) > 1]
    vals = []
    for r in rows:
        v = grid[r][1] if w > 1 else grid[r][0]
        if not vals or vals[-1] != v:
            vals.append(v)
    # Include the color of the intervening field between divider rows.
    out = []
    for i, v in enumerate(vals):
        out.append(v)
        if i + 1 < len(vals):
            out.append(grid[min(rows[i] + 1, h - 1)][0])
    return [[v] for v in out]
